func resolveRoot(flagValue string) (string, error) {
	if strings.TrimSpace(flagValue) != "" {
		return filepath.Clean(flagValue), nil
	}

	candidates := []string{}
	if cwd, err := os.Getwd(); err == nil && cwd != "" {
		candidates = append(candidates, cwd)
	}
	if exePath, err := os.Executable(); err == nil && exePath != "" {
		candidates = append(candidates, filepath.Dir(exePath))
	}

	for _, base := range candidates {
		if hasConfig(base) {
			return filepath.Clean(base), nil
		}
		if root := findConfigInAncestors(base); root != "" {
			return filepath.Clean(root), nil
		}
		if root := findConfigInSiblingRepo(base); root != "" {
			return filepath.Clean(root), nil
		}
	}

	if len(candidates) > 0 {
		return filepath.Clean(candidates[0]), nil
	}

	return "", fmt.Errorf("no working directory or executable path available")
}

func hasConfig(dir string) bool {
	p := filepath.Join(dir, "dzsj.kv-sync.json")
	if info, err := os.Stat(p); err == nil && !info.IsDir() {
		return true
	}
	return false
}

func findConfigInAncestors(start string) string {
	dir := filepath.Clean(start)
	for {
		if hasConfig(dir) {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

// When exe sits under game/dzsj/excel, the repo root is a parent that has a sibling
// dzsj-kv-sync folder containing dzsj.kv-sync.json.
func findConfigInSiblingRepo(start string) string {
	dir := filepath.Clean(start)
	for {
		sibling := filepath.Join(dir, "dzsj-kv-sync")
		if hasConfig(sibling) {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

